insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_bio_v1'
from (values
('112.42.c.5.A',2,'Which class of biomolecule stores and passes on genetic information?','["nucleic acids", "proteins", "carbohydrates", "lipids"]'::jsonb,0,'DNA and RNA are nucleic acids made of nucleotides.','original'),
('112.42.c.5.A',2,'Enzymes belong to which class of biomolecules?','["carbohydrates", "proteins", "lipids", "nucleic acids"]'::jsonb,1,'Enzymes are proteins folded into specific shapes.','original'),
('112.42.c.5.A',3,'Why do phospholipids form a double layer in a cell membrane?','["Both ends of the molecule repel water", "They are made of amino acids that bond tightly", "Their heads are attracted to water and their tails avoid water", "They store genetic information in the layer"]'::jsonb,2,'The hydrophilic heads face the watery surroundings and the hydrophobic tails face inward.','original'),
('112.42.c.5.A',2,'What are the building blocks (monomers) of proteins?','["nucleotides", "simple sugars", "fatty acids", "amino acids"]'::jsonb,3,'Amino acids join in chains to make proteins.','original'),
('112.42.c.5.A',2,'Starch and cellulose are examples of which biomolecule class?','["carbohydrates", "nucleic acids", "proteins", "lipids"]'::jsonb,0,'They are long chains of sugar units.','original'),
('112.42.c.5.A',3,'Which biomolecules are the best long-term energy storage in animals?','["amino acids", "lipids", "enzymes", "nucleic acids"]'::jsonb,1,'Fats store more energy per gram than carbohydrates.','original'),
('112.42.c.5.B',2,'Which structure do bacterial cells lack?','["a cell membrane", "DNA", "a membrane-bound nucleus", "ribosomes"]'::jsonb,2,'Prokaryotes keep their DNA in a nucleoid region without a membrane.','original'),
('112.42.c.5.B',2,'Which of these organisms is made of eukaryotic cells?','["a bacterium that lives in soil", "a cyanobacterium", "an archaeon from a hot spring", "a mushroom"]'::jsonb,3,'Fungi are eukaryotes, while bacteria and archaea are prokaryotes.','original'),
('112.42.c.5.B',3,'Which structure do both prokaryotic and eukaryotic cells have?','["ribosomes", "a nuclear envelope", "mitochondria", "an endoplasmic reticulum"]'::jsonb,0,'All cells make proteins at ribosomes.','original'),
('112.42.c.5.B',4,'According to the endosymbiotic theory, mitochondria originated from what?','["a part of the nucleus that pinched off", "small prokaryotes engulfed by a larger cell", "the Golgi apparatus", "viruses that infected early cells"]'::jsonb,1,'Evidence includes their own circular DNA and double membranes.','original'),
('112.42.c.5.B',3,'How is the DNA of a typical bacterium organized?','["as DNA packed in the mitochondria", "as RNA inside a protein coat", "as a single circular chromosome in the cytoplasm", "as many linear chromosomes inside a nucleus"]'::jsonb,2,'Prokaryotic DNA is circular and lies in the nucleoid.','original'),
('112.42.c.5.C',2,'What is the diffusion of water across a selectively permeable membrane called?','["active transport", "endocytosis", "photosynthesis", "osmosis"]'::jsonb,3,'Water moves toward the side with more dissolved solute.','original'),
('112.42.c.5.C',2,'In simple diffusion, molecules move in which direction?','["from high concentration to low concentration", "only into the nucleus", "from low concentration to high concentration", "only out of the cell"]'::jsonb,0,'Diffusion follows the concentration gradient and needs no energy.','original'),
('112.42.c.5.C',3,'What does active transport require that passive transport does not?','["a concentration gradient", "cellular energy (ATP)", "a lower temperature", "an open channel only"]'::jsonb,1,'It moves substances against their gradient.','original'),
('112.42.c.5.C',3,'A red blood cell is placed in distilled water. What most likely happens?','["It shrinks", "It stays exactly the same", "It swells and may burst", "It divides"]'::jsonb,2,'Water rushes into the cell because the outside has fewer solutes.','original'),
('112.42.c.5.C',3,'How does facilitated diffusion move a molecule across a membrane?','["by dissolving the membrane", "by pumping it against its gradient with ATP", "by engulfing it in a vesicle", "through a carrier or channel protein without using energy"]'::jsonb,3,'The molecule still moves down its gradient.','original'),
('112.42.c.5.D',2,'Why are viruses not considered cells?','["They lack organelles and cannot reproduce without a host", "They are too large to be seen", "They have a nucleus but no membrane", "They make their own food"]'::jsonb,0,'Viruses are genetic material in a protein coat.','original'),
('112.42.c.5.D',2,'What is the protein coat of a virus called?','["cell wall", "capsid", "nucleus", "flagellum"]'::jsonb,1,'The capsid protects the viral genetic material.','original'),
('112.42.c.5.D',3,'Why don''t antibiotics treat influenza?','["Antibiotics make viruses stronger", "Influenza is a parasite", "Antibiotics target bacteria, and viruses are not bacteria", "Antibiotics only work on fungi"]'::jsonb,2,'Viruses lack the structures that antibiotics attack.','original'),
('112.42.c.5.D',3,'A virus enters a host cell and uses it to make more viruses. This is the virus''s way of doing what?','["photosynthesizing", "digesting food", "respiring", "replicating"]'::jsonb,3,'Viruses hijack the host''s machinery to reproduce.','original'),
('112.42.c.6.A',2,'During which part of the cell cycle is DNA copied?','["S phase of interphase", "cytokinesis", "telophase", "metaphase"]'::jsonb,0,'The S (synthesis) phase replicates the chromosomes.','original'),
('112.42.c.6.A',3,'Mitosis produces how many cells, and how do they compare to the parent cell?','["one large cell with two nuclei", "two cells genetically identical to the parent", "two cells genetically different from each other", "four cells with half the chromosomes"]'::jsonb,1,'Mitosis makes identical diploid daughter cells.','original'),
('112.42.c.6.A',3,'What is the correct order of the stages of mitosis?','["telophase, anaphase, metaphase, prophase", "metaphase, prophase, telophase, anaphase", "prophase, metaphase, anaphase, telophase", "anaphase, prophase, metaphase, telophase"]'::jsonb,2,'PMAT.','original'),
('112.42.c.6.A',3,'In which stage of mitosis do the chromosomes line up along the center of the cell?','["telophase", "prophase", "anaphase", "metaphase"]'::jsonb,3,'The spindle fibers align them at the equator.','original'),
('112.42.c.6.A',3,'Which part of the cell cycle takes up most of the time for a typical dividing cell?','["interphase", "prophase", "anaphase", "cytokinesis"]'::jsonb,0,'Cells grow and copy DNA during interphase.','original'),
('112.42.c.6.B',3,'What is cell differentiation?','["the breakdown of a cell by enzymes", "the process by which cells become specialized in structure and function", "the movement of water across membranes", "the process by which a cell copies its DNA"]'::jsonb,1,'Different genes are switched on in different cell types.','original'),
('112.42.c.6.B',3,'A muscle cell and a nerve cell in the same person differ mainly because of what?','["different amounts of DNA", "the number of chromosomes they have", "which genes are expressed in each", "different species of DNA"]'::jsonb,2,'Both contain the same DNA but use different parts of it.','original'),
('112.42.c.6.B',2,'What is special about stem cells?','["They can never divide", "They contain no DNA", "They are always cancerous", "They are unspecialized and can differentiate into other cell types"]'::jsonb,3,'Stem cells can develop into specialized cells.','original'),
('112.42.c.6.B',4,'Which is an example of an environmental factor that can influence cell differentiation?','["chemical signals from neighboring cells", "the age of the parent''s cells", "the color of the organism''s eyes", "the number of ribosomes in the cell"]'::jsonb,0,'Signals around a developing cell help turn genes on or off.','original'),
('112.42.c.6.C',3,'Cancer is best described as what?','["a virus that infects cells", "uncontrolled cell division caused by a failure in cell cycle control", "the death of too many cells", "the failure of cells to take in nutrients"]'::jsonb,1,'Damaged control genes allow cells to keep dividing.','original'),
('112.42.c.6.C',3,'What is the role of tumor suppressor genes?','["They speed up cell division", "They create new mutations", "They slow cell division and repair DNA errors", "They make cells unable to die"]'::jsonb,2,'When they are damaged, the cell loses a brake on division.','original'),
('112.42.c.6.C',3,'Which is an example of a carcinogen?','["regular sleep", "vitamin C", "drinking water", "tobacco smoke"]'::jsonb,3,'Carcinogens cause DNA mutations that can lead to cancer.','original'),
('112.42.c.6.C',3,'What makes a tumor malignant?','["its cells can invade other tissues and spread", "it stays in one place", "it is made of fat cells", "it never grows"]'::jsonb,0,'Spreading to other body parts is called metastasis.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
