from (values
('112.42.c.7.A',2,'What three parts make up a DNA nucleotide?','["a sugar, an enzyme and water", "a sugar, a phosphate group and a nitrogen base", "a phosphate, a protein and a fatty acid", "an amino acid, a sugar and a lipid"]'::jsonb,1,'Nucleotides are the units of DNA.','original'),
('112.42.c.7.A',2,'In DNA, adenine pairs with which base?','["guanine", "cytosine", "thymine", "uracil"]'::jsonb,2,'A pairs with T and C pairs with G.','original'),
('112.42.c.7.A',3,'What part of DNA contains the code that determines traits?','["its color", "the number of hydrogen atoms", "the sugar-phosphate backbone", "the order of its nitrogen bases"]'::jsonb,3,'The base sequence is read in groups of three to specify amino acids.','original'),
('112.42.c.7.A',3,'One strand of DNA reads AATGC. What is the complementary strand?','["TTACG", "AATGC", "CCGTA", "UUACG"]'::jsonb,0,'A↔T and C↔G.','original'),
('112.42.c.7.A',2,'What is the shape of a DNA molecule?','["a hollow sphere", "a double helix", "a flat sheet", "a single straight chain"]'::jsonb,1,'Two strands twist around each other.','original'),
('112.42.c.7.B',3,'Where does transcription occur in a eukaryotic cell?','["in the lysosome", "at the ribosome", "in the nucleus", "in the cell membrane"]'::jsonb,2,'DNA is copied into mRNA inside the nucleus.','original'),
('112.42.c.7.B',3,'Where does translation occur?','["in the nucleolus", "inside the nucleus", "in the Golgi apparatus", "at a ribosome"]'::jsonb,3,'Ribosomes read mRNA to build a protein.','original'),
('112.42.c.7.B',2,'Which base does RNA use instead of thymine?','["uracil", "cytosine", "guanine", "adenine"]'::jsonb,0,'RNA contains A, U, C and G.','original'),
('112.42.c.7.B',3,'What is a codon?','["a type of protein", "a group of three mRNA bases that codes for one amino acid", "a single DNA base", "a sugar in RNA"]'::jsonb,1,'The ribosome reads mRNA one codon at a time.','original'),
('112.42.c.7.B',3,'What does a tRNA molecule do?','["it cuts proteins into pieces", "it stores the genetic code in the nucleus", "it brings the matching amino acid to the ribosome", "it copies DNA"]'::jsonb,2,'Its anticodon pairs with an mRNA codon.','original'),
('112.42.c.7.B',4,'A DNA template strand reads TAC GGT. What is the mRNA made from it?','["UAC GGU", "ATG CCA", "TAC GGT", "AUG CCA"]'::jsonb,3,'T→A, A→U, C→G and G→C.','original'),
('112.42.c.7.C',2,'What is a point mutation?','["a change in a single nucleotide of DNA", "a change in the cell membrane", "a copy of the whole genome", "the loss of an entire chromosome"]'::jsonb,0,'One base is replaced, added or removed.','original'),
('112.42.c.7.C',3,'Why is a frameshift mutation usually more harmful than a substitution?','["It never changes the protein", "It shifts the reading frame and changes every codon after it", "It repairs the DNA", "It only affects the first codon"]'::jsonb,1,'An insertion or deletion alters all the following codons.','original'),
('112.42.c.7.C',3,'A mutation that does not change the amino acid sequence is called what?','["a chromosomal deletion", "a frameshift mutation", "a silent mutation", "a nonsense mutation"]'::jsonb,2,'Several codons can code for the same amino acid.','original'),
('112.42.c.7.C',3,'A mutation in a body (somatic) cell, such as a skin cell, is passed on to offspring how?','["It is always passed on", "It is passed on to every cell in the offspring", "It is passed on only to sons", "It is not passed on"]'::jsonb,3,'Only mutations in gametes can be inherited.','original'),
('112.42.c.7.D',2,'What does PCR do?','["makes many copies of a DNA segment", "separates proteins by charge", "cuts DNA at random", "turns RNA into protein"]'::jsonb,0,'Polymerase chain reaction amplifies DNA.','original'),
('112.42.c.7.D',2,'What does gel electrophoresis separate?','["proteins from lipids by temperature", "DNA fragments by size", "cells by color", "chromosomes by number"]'::jsonb,1,'An electric current pulls DNA through a gel.','original'),
('112.42.c.7.D',3,'In gel electrophoresis, which DNA fragments travel farthest?','["the fragments with the most guanine only", "the red fragments", "the smallest fragments", "the largest fragments"]'::jsonb,2,'Small pieces move more easily through the gel.','original'),
('112.42.c.7.D',3,'Putting the human insulin gene into bacteria so they make insulin is an example of what?','["natural selection", "meiosis", "mutation by sunlight", "genetic engineering"]'::jsonb,3,'DNA from one species is inserted into another.','original'),
('112.42.c.7.D',3,'What do restriction enzymes do?','["cut DNA at specific base sequences", "join amino acids together", "make ATP", "copy RNA into DNA only"]'::jsonb,0,'They are used to cut DNA for cloning.','original'),
('112.42.c.8.A',3,'What does meiosis produce from one diploid cell?','["one haploid cell", "four genetically different haploid cells", "four identical diploid cells", "two identical diploid cells"]'::jsonb,1,'Meiosis halves the chromosome number and makes gametes.','original'),
('112.42.c.8.A',3,'During which stage of meiosis does crossing-over occur?','["anaphase II", "telophase II", "prophase I", "metaphase II"]'::jsonb,2,'Homologous chromosomes swap segments while paired.','original'),
('112.42.c.8.A',3,'What is independent assortment?','["the loss of a chromosome", "the copying of DNA", "the pairing of A with T", "the random way homologous pairs line up and separate"]'::jsonb,3,'It creates many different combinations of chromosomes in gametes.','original'),
('112.42.c.8.A',4,'A human body cell has 46 chromosomes. How many chromosomes does a human sperm cell have?','["23", "12", "46", "92"]'::jsonb,0,'Meiosis reduces the number by half.','original'),
('112.42.c.8.A',4,'Failure of chromosomes to separate properly during meiosis is called what?','["transcription", "nondisjunction", "crossing-over", "mitosis"]'::jsonb,1,'It can lead to conditions such as Down syndrome.','original'),
('112.42.c.8.B',3,'In a cross of two heterozygous parents (Tt × Tt), what fraction of offspring are expected to be tt?','["1/2", "3/4", "1/4", "0"]'::jsonb,2,'The Punnett square gives TT, Tt, Tt, tt.','original'),
('112.42.c.8.B',3,'A heterozygous parent (Tt) is crossed with a homozygous recessive parent (tt). What fraction of offspring are expected to be tt?','["all", "none", "1/4", "1/2"]'::jsonb,3,'Half of the offspring get t from the heterozygote.','original'),
('112.42.c.8.B',4,'A cross of two parents that are both RrYy (two traits) gives which phenotype ratio when each trait shows complete dominance?','["9:3:3:1", "3:1", "1:1:1:1", "1:2:1"]'::jsonb,0,'This is the classic dihybrid ratio.','original'),
('112.42.c.8.B',3,'A red snapdragon is crossed with a white snapdragon and all offspring are pink. This is an example of what?','["sex linkage", "incomplete dominance", "codominance", "complete dominance"]'::jsonb,1,'The heterozygote shows a blend.','original'),
('112.42.c.8.B',3,'A person with type AB blood shows both A and B traits. This is an example of what?','["recessive inheritance", "a mutation", "codominance", "incomplete dominance"]'::jsonb,2,'Both alleles are fully expressed.','original'),
('112.42.c.8.B',4,'Why are X-linked recessive disorders more common in males?','["Males have two X chromosomes", "Males cannot be carriers", "The Y chromosome carries the allele", "Males have only one X chromosome, so one recessive allele is expressed"]'::jsonb,3,'A single recessive allele on the X shows up in XY individuals.','original'),
('112.42.c.9.A',3,'The arm of a human and the wing of a bat have similar bone structures. What are these called?','["homologous structures", "analogous structures", "vestigial structures", "adaptive traits"]'::jsonb,0,'They suggest a common ancestor.','original'),
('112.42.c.9.A',3,'What do the fossils in layers of rock show about life on Earth?','["that the Earth is flat", "how organisms have changed over time", "that all organisms appeared at once", "that species never change"]'::jsonb,1,'The fossil record records past life in order.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
